-- 116: Original BrillaPrep WASSCE Agricultural Science beta questions, part 3.
-- Curriculum-aligned practice content; not official WAEC or NaCCA examination material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_021', 'topic_was_agric_3_1', 'subj_wassce_agric', 'exam_wassce', 'What is a leasehold interest in farmland?', 'multiple_choice', '["A. A right to use land for an agreed period under stated conditions","B. Permanent ownership without any agreement","C. Use of land for one day without consent","D. A guarantee that rent can never change"]', 'A', 'A lease grants possession and use for a defined term while ownership remains elsewhere. Written terms clarify duration, payment, permitted uses and responsibilities. Therefore the correct answer is A: A right to use land for an agreed period under stated conditions.', 'hard', 1, 1, 90, 'st_was_agric_3_1', 'Identify', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_022', 'topic_was_agric_3_1', 'subj_wassce_agric', 'exam_wassce', 'How can insecure land tenure discourage long-term farm investment?', 'multiple_choice', '["A. It always increases access to credit","B. A farmer may fear losing the land before the investment pays back","C. It makes trees mature faster","D. It removes every boundary dispute automatically"]', 'B', 'Irrigation, soil improvement and tree crops may take years to recover their cost. Uncertain rights reduce confidence that the farmer will receive those future benefits. Therefore the correct answer is B: A farmer may fear losing the land before the investment pays back.', 'easy', 2, 2, 90, 'st_was_agric_3_1', 'Explain', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_023', 'topic_was_agric_3_1', 'subj_wassce_agric', 'exam_wassce', 'Which action best reduces disputes before cultivating land obtained through customary arrangements?', 'multiple_choice', '["A. Rely only on an unverified rumour","B. Move boundary markers secretly","C. Confirm the authorised grant, boundaries, witnesses and terms in a documented process","D. Assume unused land has no recognised interests"]', 'C', 'Customary rights are legitimate but can involve several authorities and interests. Verification and clear documentation protect both the landholder and the farmer. Therefore the correct answer is C: Confirm the authorised grant, boundaries, witnesses and terms in a documented process.', 'medium', 1, 1, 90, 'st_was_agric_3_1', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_024', 'topic_was_agric_3_1', 'subj_wassce_agric', 'exam_wassce', 'Under sharecropping, how is the landholder commonly compensated?', 'multiple_choice', '["A. Only with ownership of all the farmer’s tools","B. By receiving the entire harvest regardless of terms","C. With rainfall measured during the season","D. With an agreed share of the farm output or proceeds"]', 'D', 'Sharecropping arrangements divide output or revenue according to an agreed formula. Clear terms should cover inputs, risk, harvest measurement and each party’s share. Therefore the correct answer is D: With an agreed share of the farm output or proceeds.', 'hard', 2, 2, 90, 'st_was_agric_3_1', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_025', 'topic_was_agric_3_2', 'subj_wassce_agric', 'exam_wassce', 'What is the central role of an agricultural extension officer?', 'multiple_choice', '["A. Help farmers evaluate and apply relevant knowledge and technologies","B. Set every market price by law","C. Operate every farm on behalf of owners","D. Replace all farmer experimentation"]', 'A', 'Extension connects research, local experience and practical advisory support. Participatory approaches help farmers adapt recommendations to their conditions. Therefore the correct answer is A: Help farmers evaluate and apply relevant knowledge and technologies.', 'easy', 3, 3, 90, 'st_was_agric_3_2', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_026', 'topic_was_agric_3_2', 'subj_wassce_agric', 'exam_wassce', 'How can a farmer cooperative improve members’ bargaining position?', 'multiple_choice', '["A. By preventing members from keeping records","B. By pooling demand or produce to negotiate at useful scale","C. By hiding quality information from buyers","D. By eliminating every production cost"]', 'B', 'Collective purchasing and marketing can reduce transaction costs and strengthen negotiation. Transparent governance and agreed quality standards remain essential. Therefore the correct answer is B: By pooling demand or produce to negotiate at useful scale.', 'medium', 2, 2, 90, 'st_was_agric_3_2', 'Explain', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_027', 'topic_was_agric_3_2', 'subj_wassce_agric', 'exam_wassce', 'Why should a farmer compare the effective cost and repayment schedule before taking credit?', 'multiple_choice', '["A. Because interest never affects profitability","B. Because all lenders offer identical terms","C. To confirm expected cash flow can service the loan without undermining the farm","D. To avoid preparing an enterprise budget"]', 'C', 'Loan principal, interest, fees and due dates affect working capital. A realistic cash-flow forecast shows whether income is likely to arrive before repayments fall due. Therefore the correct answer is C: To confirm expected cash flow can service the loan without undermining the farm.', 'hard', 1, 1, 90, 'st_was_agric_3_2', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_028', 'topic_was_agric_3_2', 'subj_wassce_agric', 'exam_wassce', 'What risk does index-based agricultural insurance usually pay against?', 'multiple_choice', '["A. Every individual loss without a policy condition","B. Changes in the farmer’s preferred crop colour","C. Guaranteed profit regardless of management","D. A measured trigger such as rainfall falling below a defined threshold"]', 'D', 'Index insurance pays when an agreed external measure crosses a threshold. It can speed settlement, but basis risk exists when the index differs from a farmer’s actual loss. Therefore the correct answer is D: A measured trigger such as rainfall falling below a defined threshold.', 'easy', 2, 2, 90, 'st_was_agric_3_2', 'Identify', 'AO1', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_029', 'topic_was_agric_4_1', 'subj_wassce_agric', 'exam_wassce', 'Which statement correctly distinguishes weather from climate?', 'multiple_choice', '["A. Weather describes short-term conditions, while climate summarises long-term patterns","B. Weather and climate always mean the same day","C. Climate is measured for only one hour","D. Weather cannot include rainfall"]', 'A', 'Weather records conditions over short periods. Climate uses long-term statistics and patterns, although individual seasons can still differ from the average. Therefore the correct answer is A: Weather describes short-term conditions, while climate summarises long-term patterns.', 'medium', 1, 1, 90, 'st_was_agric_4_1', 'Identify', 'AO2', 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, syllabus_topic_id, command_word, assessment_objective, exam_board_id) VALUES ('q_was_agric_b001_030', 'topic_was_agric_4_1', 'subj_wassce_agric', 'exam_wassce', 'How can a prolonged drought reduce crop yield?', 'multiple_choice', '["A. It guarantees greater leaf expansion","B. Water stress limits photosynthesis, nutrient movement and growth","C. It makes soil water permanently abundant","D. It prevents every pest outbreak"]', 'B', 'Insufficient water causes stomata to close and reduces cell expansion and nutrient transport. Timing matters because flowering and grain filling can be especially sensitive. Therefore the correct answer is B: Water stress limits photosynthesis, nutrient movement and growth.', 'hard', 3, 3, 90, 'st_was_agric_4_1', 'Explain', 'AO3', 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-agric-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Agricultural Science curriculum; not official WAEC or NaCCA examination material.', 'https://nacca.gov.gh/wp-content/uploads/2025/04/Agricultural-Science-Curriculum.pdf', 0, 1 FROM questions WHERE id BETWEEN 'q_was_agric_b001_021' AND 'q_was_agric_b001_030';
